//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//	NAME:					HE_ATV320_RuntimeData
//	CREATOR:				Helgevold - Jan Magne Dybvik
// REQUIREMENTS: NX CPU // Schneider ATV320
//
// DESCRTIPTION: 	Read spesific data from schneider ATV320 VFD - Explicit message
//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//  VERSION LOG:
//	 VERSION			DATE				SIGN						DESCRIPTION
//	 1.0					2023-10-26		Jan Magne Dybvik		Initial release
//	 1.1					2023-11-01		Jan Magne Dybvik		Endret IP adresse til RoutePath, bug fix
//  2.0					2023-11-27		Jan Magne Dybvik		Lagt til avlsening av Frekvensomformer tilstand/modus
//  2.1					2023-12-18		Jan Magne Dybvik		Lagt til avlesning av Motorstrøm, og sørget for at sekvensen avbrytes ved første feil for å korte ned ventetiden.
//  2.1.1				2023-12-20		Jan Magne Dybvik		Energimåling pr. dag. Driftstid og Påtid i dager
//	 2.1.2				2024-09-27		Ruben Byman				Endret .Intern.Status_Servicebryter til .Intern.GeneralMessage
//	 3.0.0				2025-10-11		William Veim				Total rework, telegram strucutre edited and implemented in wrapper block
//	 3.1.0				2026-05-07		William Veim				Added reading og NPR value
//
//================================================================================================================================

(*
	Funkjonsblokken bentytter seg av CIPUCMMSend instuksjonen. Den er felles for alle instansene av denne funksjonsblokken.
	Kun en instans får bruke CIPUCMMSend av gangen. Det bestemmes av Ext_TokenID og Ext_Telegram.Token.
	Ext_TokenID blir inkrementert i hver instans slik at alle har unikt nummer.
	Når en instans har matchende verdi kan den benytte seg av CIPUCMMSend.
	Når instansen er ferdig inkrementeres  Ext_Telegram.Token slik at neste instans får bruke CIPUCMMSend.
	Etter siste instans blir Ext_TokenID og Ext_Telegram.Token igjen sammenlignet og hvis de er like har alle instanser kjørt og Ext_Telegram.Token resettes.
	
	Routing: Når en benytter Ethernet/IP interface integrert i CPU er det ikke behov for routing da vil Cfg_RoutePath være '02\[IP ADDR]'		(f.eks: '02\10.128.218.11')
	Når en benytter en add-on modul må en konfigurere Routing. Da vil Cfg_RoutePath være '[Backplane]\#[([X Bus Unit No.]*10) + ([Port No.]-1)]\02\[IP ADDR]'		(f.eks: '01\#10\02\10.128.118.11') for å gå via Add-on modul 1 port 1

*)

//================================================================================================================================

(*************************************************************************
 *	ASSIGNS TOKEN
 *************************************************************************)
 
IF TokenID = -1 THEN
	FOR TokenID:=0 TO DINT_TO_UINT(UPPER_BOUND(Ext_Telegram.Token_Static, 1)) DO
		IF NOT Ext_Telegram.Token_Static[TokenID] THEN
			Ext_Telegram.Token_Static[TokenID]:=TRUE;
			EXIT;
		END_IF;
	END_FOR;
END_IF;

(*************************************************************************
 *	CASE FOR REQUEST & DATA SEND
 *************************************************************************)

CASE Wrk_State OF
	
	0: // Wait for turn
	
		IF Ext_Telegram.Token_Active = TokenID THEN
			
			Ext_Telegram.RoutePath := Cfg_RoutePath;
			Ext_Telegram.ServiceCode :=16#0E;
			Ext_Telegram.Size :=0;
			Ext_Telegram.ReqPath.ClassIDLogicalFormat:=_16BIT;
			Ext_Telegram.ReqPath.InstanceIDLogicalFormat:=_16BIT;
			Ext_Telegram.ReqPath.AttributeIDLogicalFormat:=_16BIT;
			Ext_Telegram.ReqPath.isAttributeID := TRUE;
			Ext_Telegram.ReqPath.ClassID := 16#71;
			Ext_Telegram.ReqPath.InstanceID :=16#1;
			
			Wrk_State := 10;
		END_IF;
			
	10: // Start Read APH (Energy Consumption)

		IF Ext_Telegram.Ready THEN
			Ext_Telegram.ReqPath.AttributeID := 16#1F;
			Ext_Telegram.Ready := 	FALSE;
			Ext_Telegram.Execute := TRUE;
		
			Wrk_State := 11;
		END_IF;
	
	11: // Wait for completion
		
		IF Ext_Telegram.Sucsess THEN
			Wrk_APH_Raw := WORD_TO_UINT(Ext_Telegram.RespServiceData.Wrd[0]);
			Wrk_APH_Valid := Ext_Telegram.RespSize>0;
			Wrk_APH_Success := Wrk_APH_Success + 1;
			Ext_Telegram.Sucsess := FALSE;
			Ext_Telegram.Execute := FALSE;
			
			Wrk_State := 20;
			
		ELSIF Ext_Telegram.Error THEN
			Wrk_APH_Valid := FALSE;
			Wrk_APH_ErrorID := Ext_Telegram.ErrorID;
			Wrk_APH_Failure := Wrk_APH_Failure + 1;
			Ext_Telegram.Error := FALSE;
			Ext_Telegram.Execute := FALSE;
			
			Wrk_State := 1001;
		END_IF;
	
	20: // Start Read RTH (Motor run time)

		IF Ext_Telegram.Ready THEN
			Ext_Telegram.ReqPath.AttributeID := 16#20;
			Ext_Telegram.Ready := 	FALSE;
			Ext_Telegram.Execute :=  TRUE;
		
			Wrk_State := 21;
		END_IF;
	
	21: // Wait for completion
		
		IF Ext_Telegram.Sucsess THEN
			Wrk_RTH_Raw := WORD_TO_UINT(Ext_Telegram.RespServiceData.Wrd[0]);
			Wrk_RTH_Valid := Ext_Telegram.RespSize>0;
			Wrk_RTH_Success := Wrk_RTH_Success + 1;
			Ext_Telegram.Sucsess := FALSE;
			Ext_Telegram.Execute := FALSE;
			
			Wrk_State := 30;
			
		ELSIF Ext_Telegram.Error THEN
			Wrk_RTH_Valid := FALSE;
			Wrk_RTH_ErrorID := Ext_Telegram.ErrorID;
			Wrk_RTH_Failure := Wrk_RTH_Failure + 1;
			Ext_Telegram.Error := FALSE;
			Ext_Telegram.Execute := FALSE;
			
			Wrk_State := 1001;
		END_IF;
		
	30: // Start Read PTH (Power on time)

		IF Ext_Telegram.Ready THEN
			Ext_Telegram.ReqPath.AttributeID := 16#22;
			Ext_Telegram.Ready := 	FALSE;
			Ext_Telegram.Execute :=  TRUE;
		
			Wrk_State := 31;
		END_IF;
	
	31: // Wait for completion
		
		IF Ext_Telegram.Sucsess THEN
			Wrk_PTH_Raw := WORD_TO_UINT(Ext_Telegram.RespServiceData.Wrd[0]);
			Wrk_PTH_Valid := Ext_Telegram.RespSize>0;
			Wrk_PTH_Success := Wrk_PTH_Success + 1;
			Ext_Telegram.Sucsess := FALSE;
			Ext_Telegram.Execute := FALSE;
			
			Wrk_State := 40;
			
		ELSIF Ext_Telegram.Error THEN
			Wrk_PTH_Valid := FALSE;
			Wrk_PTH_ErrorID := Ext_Telegram.ErrorID;
			Wrk_PTH_Failure := Wrk_PTH_Failure + 1;
			Ext_Telegram.Error := FALSE;
			Ext_Telegram.Execute := FALSE;
			
			Wrk_State := 1001;
		END_IF;
		
	40: // Start Read UNT (Units for APH, RTH and PTH)

		IF Ext_Telegram.Ready THEN
			Ext_Telegram.ReqPath.AttributeID := 16#23;
			Ext_Telegram.Ready := 	FALSE;
			Ext_Telegram.Execute :=  TRUE;
		
			Wrk_State := 41;
		END_IF;
	
	41: // Wait for completion
		
		IF Ext_Telegram.Sucsess THEN
			Wrk_UNT := Ext_Telegram.RespServiceData.Wrd[0];
			Wrk_UNT_Valid := Ext_Telegram.RespSize>0;
			Wrk_UNT_Success := Wrk_UNT_Success + 1;
			Ext_Telegram.Sucsess := FALSE;
			Ext_Telegram.Execute := FALSE;
			
			Wrk_State := 50;
			
		ELSIF Ext_Telegram.Error THEN
			Wrk_UNT_Valid := FALSE;
			Wrk_UNT_ErrorID := Ext_Telegram.ErrorID;
			Wrk_UNT_Failure := Wrk_UNT_Failure + 1;
			Ext_Telegram.Error := FALSE;
			Ext_Telegram.Execute := FALSE;
			
			Wrk_State := 1001;
		END_IF;
		
	50: // Start Read HMIS (Drive State)
	
		IF Ext_Telegram.Ready THEN
			Ext_Telegram.ReqPath.AttributeID := 16#29;
			Ext_Telegram.Ready := 	FALSE;
			Ext_Telegram.Execute := TRUE;
		
			Wrk_State := 51;
		END_IF;
	
	51: // Wait for completion
		
		IF Ext_Telegram.Sucsess THEN
			Wrk_HMIS_Raw := Ext_Telegram.RespServiceData.Wrd[0];
			Wrk_HMIS_Valid :=  Ext_Telegram.RespSize>0;
			Wrk_HMIS_Success := Wrk_HMIS_Success + 1;
			Ext_Telegram.Sucsess := FALSE;
			Ext_Telegram.Execute := FALSE;

			Wrk_State := 60;
			
		ELSIF Ext_Telegram.Error THEN
			Wrk_HMIS_Valid := FALSE;
			Wrk_HMIS_ErrorID := Ext_Telegram.ErrorID;
			Wrk_HMIS_Failure := Wrk_HMIS_Failure + 1;
			Ext_Telegram.Error := FALSE;
			Ext_Telegram.Execute := FALSE;
			
			Wrk_State := 1001;
		END_IF;
		
	60: // Start Read LCR (Motor Current)

		IF Ext_Telegram.Ready THEN
			Ext_Telegram.ReqPath.AttributeID := 16#5;
			Ext_Telegram.Ready := 	FALSE;
			Ext_Telegram.Execute := TRUE;
		
			Wrk_State := 61;
		END_IF;
	
	61: // Wait for completion
		
		IF Ext_Telegram.Sucsess THEN
			Wrk_LCR_Raw := 			Ext_Telegram.RespServiceData.Wrd[0];
			Wrk_LCR_Valid := 		Ext_Telegram.RespSize>0;
			Wrk_LCR_Success := 	Wrk_LCR_Success + 1;
			Ext_Telegram.Sucsess := FALSE;
			Ext_Telegram.Execute := FALSE;
			
			Wrk_State := 70;
			
		ELSIF Ext_Telegram.Error THEN
			Wrk_LCR_Valid := FALSE;
			Wrk_LCR_ErrorID := Ext_Telegram.ErrorID;
			Wrk_LCR_Failure := Wrk_LCR_Failure + 1;
			Ext_Telegram.Error := FALSE;
			Ext_Telegram.Execute := FALSE;
			
			Wrk_State := 1001;
		END_IF;
		
	70: // Start Read NPR (Motor rated power)

		IF Ext_Telegram.Ready THEN
			Ext_Telegram.ReqPath.ClassID := 16#91;
			Ext_Telegram.ReqPath.AttributeID := 16#0E;
			Ext_Telegram.Ready := 	FALSE;
			Ext_Telegram.Execute := TRUE;
		
			Wrk_State := 71;
		END_IF;
	
	71: // Wait for completion
		
		IF Ext_Telegram.Sucsess THEN
			Wrk_NPR_Raw := Ext_Telegram.RespServiceData.Wrd[0];
			Wrk_NPR_Valid := Ext_Telegram.RespSize>0;
			Wrk_NPR_Success := Wrk_LCR_Success + 1;
			Ext_Telegram.Sucsess := FALSE;
			Ext_Telegram.Execute := FALSE;
			
			Wrk_State := 1000;
			
		ELSIF Ext_Telegram.Error THEN
			Wrk_NPR_Valid := FALSE;
			Wrk_NPR_ErrorID := Ext_Telegram.ErrorID;
			Wrk_NPR_Failure := Wrk_LCR_Failure + 1;
			Ext_Telegram.Error := FALSE;
			Ext_Telegram.Execute := FALSE;
			
			Wrk_State := 1001;
		END_IF;
		
	1000: //Completed and valid
	
		IF Wrk_UNT_Valid THEN
			Wrk_APH_Unit := Wrk_UNT & WORD#16#3; // Mask of APH unit bits
			Wrk_PTH_Unit := SHR(Wrk_UNT, 2) & WORD#16#3; // Shift of PTH bits to first two bits, and mask of bits
			Wrk_RTH_Unit := SHR(Wrk_UNT, 4) & WORD#16#3; // Shift of RTH bits to first two bits, and mask of bits
			
			IF Wrk_APH_Valid THEN
					Wrk_APH := Wrk_APH_Raw; // kWh
			ELSE
					Wrk_APH :=0;
			END_IF;
			
			IF Wrk_PTH_Valid  THEN
					Wrk_PTH := Wrk_PTH_Raw * 3600; // Hours
			ELSE
					Wrk_PTH := 0;
			END_IF;
					
			IF Wrk_RTH_Valid  THEN
					Wrk_RTH := Wrk_RTH_Raw * 3600; // Hours
			ELSE
					Wrk_RTH :=0;
			END_IF;
			
		END_IF;
		
		IF Wrk_HMIS_Valid  THEN
			Wrk_HMIS := Wrk_HMIS_Raw;
		END_IF;
		
		IF Wrk_LCR_Valid  THEN 
			Wrk_LCR := INT_TO_REAL(WORD_TO_INT(Wrk_LCR_Raw)) / 10.0;
		END_IF;
		
		IF Wrk_NPR_Valid THEN
			Wrk_NPR:=WORD_TO_REAL(Wrk_NPR_Raw);
		END_IF;
		 
		Inc(Ext_Telegram.Token_Active);
	
	1001: // General error
	
		Inc(Ext_Telegram.Token_Active);

END_CASE;

IF Ext_Telegram.Token_Active <> TokenID THEN
			Wrk_State := 0;
END_IF;

// Update Outputs
Val_APH := 	Wrk_APH;
Val_PTH := 	Wrk_PTH;
Val_RTH := 	Wrk_RTH;
Val_LCR :=  	Wrk_LCR;
Val_NPR:= 	Wrk_NPR;
Val_HMIS := WORD_TO_UINT(Wrk_HMIS);
